import { FocusOrigin } from '@angular/cdk/a11y';
import { CdkOverlayOrigin } from '@angular/cdk/overlay';
import {
  AfterContentInit,
  Directive,
  ElementRef,
  HostListener,
  Input,
  inject,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { ENTER, RIGHT_ARROW } from '@questrade/allspark-angular-components/core/utils';
import { Observable, asapScheduler, delay, filter, merge, of, takeUntil } from 'rxjs';
import { QLegacyMenuItemComponent } from './menu-item/menu-item.component';
import { QMenuCloseReason } from './types/menu-close-reason.type';
import { Q_MENU_PANEL } from './types/menu-panel.const';
import { QMenuPanel } from './types/menu-panel.interface';

/**
 * @deprecated Use QMenuTriggerDirective instead, To be removed.
 * @breaking-change First major after Fev 26, 2026
 */
@Directive({
  selector: '[qMenuTriggerFor], [q-menu-trigger-for]',
  providers: [QDestroyService],
})
export class QLegacyMenuTriggerDirective implements AfterContentInit {
  @Input('qMenuTriggerFor') get menu(): QMenuPanel {
    return this._menu;
  }
  set menu(menu: QMenuPanel) {
    if (menu === this._menu) {
      return;
    }

    if (this._overlayOrigin) {
      menu.openedBy = this._overlayOrigin;
    }

    this._menu = menu;

    this.menu.closed.pipe(takeUntil(this._destroy$)).subscribe((reason: QMenuCloseReason) => {
      this._closeMenu(reason);

      if ((reason === 'click' || reason === 'tab') && this.parentMenu) {
        this.parentMenu.closed.emit(reason);
      }
    });
  }

  @HostListener('click', ['$event']) _handleClick(event: Event): void {
    if (this.isTriggerForSubmenu) {
      event.stopPropagation();
    } else {
      this._toggle();
    }
  }

  @HostListener('mouseleave', ['$event']) _handleMouseLeave({ relatedTarget }: MouseEvent): void {
    if (
      this.menuItemInstance
        ?.getHostElement()
        ?.parentElement?.parentElement?.isEqualNode(relatedTarget as Node)
    ) {
      this._highlightMenuItem(false);
      this.menu.closed.emit();
    } else {
      this._highlightMenuItem(this.menu.isOpened);
    }

    this.parentMenu?.directDescendantItems.forEach((item) => {
      if (item?.getHostElement()?.parentElement?.contains(relatedTarget as Node)) {
        this.menu.closed.emit();
      }
    });
  }

  @HostListener('keydown', ['$event']) _handleKeydown(event: KeyboardEvent): void {
    const code = event.code;

    if (this.isTriggerForSubmenu && [RIGHT_ARROW, ENTER].includes(code)) {
      this._openMenu('keyboard');
      event.stopPropagation();
      event.preventDefault();
    }
  }

  private _menu!: QMenuPanel;
  private _overlayOrigin: CdkOverlayOrigin | null = null;
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly menuItemInstance = inject(QLegacyMenuItemComponent, {
    optional: true,
    self: true,
  });
  private readonly parentMenu = inject<QMenuPanel>(Q_MENU_PANEL, { optional: true });

  constructor() {
    const menuItemInstance = this.menuItemInstance;
    const parentMenu = this.parentMenu;

    this._overlayOrigin = new CdkOverlayOrigin(this._elementRef);

    if (parentMenu) {
      this.parentMenu.closed
        .pipe(takeUntil(this._destroy$))
        .subscribe((reason: QMenuCloseReason) => {
          if (this.menu.isOpened) {
            this._closeMenu(reason);
          }
        });
    }

    if (menuItemInstance) {
      menuItemInstance.triggersSubmenu = this.isTriggerForSubmenu;
    }
  }

  ngAfterContentInit(): void {
    this._handleHover();
  }

  get isTriggerForSubmenu(): boolean {
    return !!this.parentMenu;
  }

  private _highlightMenuItem(selected: boolean): void {
    this.menuItemInstance?.setHighlighted(selected);
    this.menuItemInstance?.setSelected(selected);
  }

  private _toggle(): void {
    if (this.menu.isOpened) {
      this._closeMenu(undefined);
    } else {
      this._openMenu();
    }
  }

  private _openMenu(openedBy: FocusOrigin = 'program'): void {
    if (this.menu.isOpened) return;

    this.menu.isSubmenu = this.isTriggerForSubmenu;

    this._menuClosingActions()
      .pipe(takeUntil(this._destroy$))
      .subscribe(() => this._closeMenu(undefined));

    this.menu.open();
    this.menu.focusFirstItem(openedBy);
  }

  private _closeMenu(reason: QMenuCloseReason): void {
    if (this.menu.isOpened) {
      this.menu?.close(reason);

      this._highlightMenuItem(false);

      if (reason === 'keydown') {
        this._elementRef.nativeElement.focus();
      }
    }
  }

  private _menuClosingActions(): Observable<QMenuCloseReason | QLegacyMenuItemComponent> {
    const parentClose = this.parentMenu ? this.parentMenu.closed : of();
    const hover = this.parentMenu
      ? this.parentMenu.itemHovered().pipe(
          filter((active) => active !== this.menuItemInstance),
          filter(() => this.menu.isOpened),
        )
      : of();

    return merge(parentClose as Observable<QMenuCloseReason>, hover);
  }

  private _handleHover(): void {
    if (!this.isTriggerForSubmenu || !this.parentMenu) {
      return;
    }

    this.parentMenu
      .itemHovered()
      // Since we might have multiple competing triggers for the same menu (e.g. a sub-menu
      // with different data and triggers), we have to delay it by a tick to ensure that
      // it won't be closed immediately after it is opened.
      .pipe(
        filter((active) => active === this.menuItemInstance && !active.disabled),
        delay(0, asapScheduler),
        takeUntil(this._destroy$),
      )
      .subscribe(() => {
        this._openMenu('mouse');
      });
  }
}
