import { FocusableOption, FocusMonitor, FocusOrigin } from '@angular/cdk/a11y';
import { NgIf } from '@angular/common';
import {
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  HostBinding,
  HostListener,
  inject,
  Input,
  OnDestroy,
  ViewEncapsulation,
} from '@angular/core';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { chevronRight } from '@questrade/allspark-icons/icons';
import { Subject } from 'rxjs';
import { QLegacyMenuComponent } from '../menu.component';
import { Q_MENU_PANEL } from '../types/menu-panel.const';

/**
 * @deprecated Use QMenuItemComponent instead, To be removed.
 * @breaking-change First major after Fev 26, 2026
 */
@Component({
  selector: '[q-menu-item]',
  imports: [NgIf, QIconComponent],
  templateUrl: './menu-item.component.html',
  styleUrls: ['./menu-item.component.scss'],
  host: {
    class: 'q-legacy-menu-item q-focus-indicator-inset',
    '[attr.role]': "'menuitem'",
    '[attr.disabled]': 'disabled || null',
    '[attr.tabindex]': '_getTabIndex()',
    '[class.highlighted]': '_highlighted',
    '[class.selected]': '_selected',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QLegacyMenuItemComponent implements AfterViewInit, OnDestroy, FocusableOption {
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-menu-item';

  @Input('parentMenu') set _parentMenu(value: QLegacyMenuComponent | undefined) {
    if (!value) {
      return;
    }

    this.parentMenu = value;
  }

  // Prevents the default element actions if it is disabled.
  // We have to use a `HostListener` here in order to support both Ivy and ViewEngine.
  // In Ivy the `host` bindings will be merged when this class is extended, whereas in
  // ViewEngine they're overwritten
  @HostListener('click', ['$event']) _onItemClick(event: Event): void {
    if (this.disabled || this.triggersSubmenu) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }

    this.parentMenu?.closed.emit('click');
  }

  // Emits to the hover stream.
  // We have to use a `HostListener` here in order to support both Ivy and ViewEngine.
  // In Ivy the `host` bindings will be merged when this class is extended, whereas in
  // ViewEngine they're overwritten.
  @HostListener('mouseenter') _handleMouseEnter(): void {
    this.hovered.next(this);
  }

  @HostListener('mouseleave') _handleMouseLeave(): void {
    this._selected = false;
  }

  @HostListener('mousedown') _handleMouseDown(): void {
    this._selected = true;
  }

  @HostListener('mouseup') _handleMouseUp(): void {
    this._selected = false;
  }

  _highlighted = false;
  _selected = false;
  triggersSubmenu = false;
  parentMenu!: QLegacyMenuComponent;
  readonly hovered = new Subject<QLegacyMenuItemComponent>();
  readonly focused = new Subject<QLegacyMenuItemComponent>();

  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _elementRef = inject(ElementRef<HTMLElement>);
  private readonly _focusMonitor = inject(FocusMonitor);

  constructor() {
    const parentMenu = inject<QLegacyMenuComponent>(Q_MENU_PANEL, { optional: true });

    this._parentMenu = parentMenu ?? undefined;
    this._iconRegistry.registerIcons([chevronRight]);
  }

  ngAfterViewInit(): void {
    if (this._focusMonitor) {
      // Start monitoring the element so it gets the appropriate focused classes. We want
      // to show the focus style for menu items only when the focus was not caused by a
      // mouse or touch interaction.
      this._focusMonitor.monitor(this._elementRef, false);
    }
  }

  ngOnDestroy(): void {
    if (this._focusMonitor) {
      this._focusMonitor.stopMonitoring(this._elementRef);
    }

    this.hovered.complete();
    this.focused.complete();
  }

  _getTabIndex(): string {
    return this.disabled ? '-1' : '0';
  }

  focus(origin?: FocusOrigin, options?: FocusOptions): void {
    if (this._focusMonitor && origin) {
      this._focusMonitor.focusVia(this.getHostElement(), origin, options);
    } else {
      this.getHostElement().focus(options);
    }

    this.focused.next(this);
  }

  getHostElement(): HTMLElement {
    return this._elementRef.nativeElement;
  }

  getLabel(): string {
    const clone = this._elementRef.nativeElement.cloneNode(true) as HTMLElement;

    return clone.textContent?.trim() || '';
  }

  setHighlighted(isHighlighted: boolean): void {
    this._highlighted = isHighlighted;
  }

  setSelected(isSelected: boolean): void {
    this._selected = isSelected;
  }
}
