import { FocusKeyManager, FocusOrigin } from '@angular/cdk/a11y';
import { coerceArray } from '@angular/cdk/coercion';
import { hasModifierKey } from '@angular/cdk/keycodes';
import { CdkOverlayOrigin, ConnectionPositionPair } from '@angular/cdk/overlay';
import {
  AfterContentInit,
  ChangeDetectionStrategy,
  Component,
  ContentChildren,
  EventEmitter,
  HostBinding,
  Input,
  Output,
  QueryList,
  ViewChild,
  ViewEncapsulation,
  forwardRef,
  inject,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { ESCAPE, LEFT_ARROW, TAB } from '@questrade/allspark-angular-components/core/utils';
import {
  QOverlayComponent,
  QOverlayPositionX,
  QOverlayPositionY,
  QOverlayPriorityPosition,
} from '@questrade/allspark-angular-components/overlay';
import { Observable, merge, startWith, switchMap, takeUntil } from 'rxjs';
import { QLegacyMenuItemComponent } from './menu-item/menu-item.component';
import { QMenuCloseReason } from './types/menu-close-reason.type';
import { Q_MENU_PANEL } from './types/menu-panel.const';
import { QMenuPanel } from './types/menu-panel.interface';

/**
 * @deprecated Use QMenuComponent instead, To be removed.
 * @breaking-change First major after Fev 26, 2026
 */
@Component({
  selector: 'q-menu',
  imports: [QOverlayComponent],
  templateUrl: './menu.component.html',
  styleUrls: ['./menu.component.scss'],
  providers: [{ provide: Q_MENU_PANEL, useExisting: QLegacyMenuComponent }, QDestroyService],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QLegacyMenuComponent implements QMenuPanel, AfterContentInit {
  @Output() readonly opened = new EventEmitter<void>();
  @Output() readonly closed = new EventEmitter<QMenuCloseReason>();

  @Input() xPosition: QOverlayPositionX = 'start';
  @Input() yPosition: QOverlayPositionY = 'below';
  @Input() priorityPositions: QOverlayPriorityPosition = 'vertical';
  @Input() offsetY = 4;
  @Input() offsetX = 4;
  @Input() dataQt = 'q-menu';

  @Input() get overlayPanelClass(): string | string[] {
    return this._overlayPanelClass;
  }
  set overlayPanelClass(value: string | string[]) {
    const overlayClasses = coerceArray(value || []).filter((clName) => !!clName);
    this._overlayPanelClass = ['q-overlay-panel', 'q-legacy-menu-overlay-panel', ...overlayClasses];
  }

  @ContentChildren(forwardRef(() => QLegacyMenuItemComponent), { descendants: true })
  private _allMenuItems!: QueryList<QLegacyMenuItemComponent>;

  @ViewChild('overlay') _overlay!: QOverlayComponent;

  @HostBinding('class') _hostClass = 'q-legacy-menu';

  openedBy!: CdkOverlayOrigin;
  directDescendantItems = new QueryList<QLegacyMenuItemComponent>();
  _isSubmenu = false;

  private _overlayPanelClass: string | string[] = [
    'q-overlay-panel',
    'q-legacy-menu-overlay-panel',
  ];
  private _keyManager: FocusKeyManager<QLegacyMenuItemComponent> | null = null;
  private readonly _destroy$ = inject(QDestroyService);

  ngAfterContentInit(): void {
    this._updateDirectDescendants();

    this._keyManager = new FocusKeyManager(this.directDescendantItems)
      .withWrap()
      .withTypeAhead()
      .withHomeAndEnd();

    this.directDescendantItems.changes
      .pipe(
        startWith(this.directDescendantItems),
        switchMap((items) => merge(...items.map((item: QLegacyMenuItemComponent) => item.focused))),
        takeUntil(this._destroy$),
      )
      .subscribe((focusedItem) =>
        this._keyManager?.updateActiveItem(focusedItem as QLegacyMenuItemComponent),
      );
  }

  open(): void {
    this._overlay.opened.pipe(takeUntil(this._destroy$)).subscribe(() => this.opened.emit());

    this._overlay.closed
      .pipe(takeUntil(this._destroy$))
      .subscribe((event: undefined | KeyboardEvent | MouseEvent) => {
        if (event instanceof MouseEvent) {
          this.closed.emit('click');
        } else if (event instanceof KeyboardEvent) {
          this.closed.emit('keydown');
        }
      });

    if (this.isSubmenu) {
      this._overlay.xPosition = 'right';
      this._overlay.yPosition = 'above';
      this._overlay.priorityPositions = 'horizontal';
    }

    this._overlay.open();
  }

  close(reason: QMenuCloseReason): void {
    this._overlay.close();
    this.closed.emit(reason);
  }

  _handleKeydown(event: KeyboardEvent): void {
    const keyCode = event.code;

    switch (keyCode) {
      case ESCAPE:
        if (!hasModifierKey(event)) {
          event.preventDefault();
          event.stopPropagation();
          this.closed.emit('keydown');
        }

        break;
      case TAB:
        event.preventDefault();
        this.closed.emit('tab');
        break;
      case LEFT_ARROW:
        if (this.isSubmenu) {
          this.closed.emit('keydown');
        }

        break;
      default:
        this._keyManager?.onKeydown(event);
    }
  }

  itemHovered(): Observable<QLegacyMenuItemComponent> {
    const itemChanges = this.directDescendantItems.changes as Observable<
      QueryList<QLegacyMenuItemComponent>
    >;

    return itemChanges.pipe(
      startWith(this.directDescendantItems),
      switchMap((items) => merge(...items.map((item: QLegacyMenuItemComponent) => item.hovered))),
    );
  }

  focusFirstItem(openedBy: FocusOrigin): void {
    if (openedBy === 'mouse') return;

    this._keyManager?.setFocusOrigin(openedBy).setFirstItemActive();

    if (!this._keyManager?.activeItem && this.directDescendantItems.length) {
      let element = this.directDescendantItems.first.getHostElement().parentElement;

      while (element) {
        if (element.getAttribute('role') === 'menu') {
          element.focus();
          break;
        }

        element = element.parentElement;
      }
    }
  }

  get isSubmenu(): boolean {
    return this._isSubmenu;
  }

  set isSubmenu(value: boolean) {
    this._isSubmenu = value;
    this._overlay.hasBackdrop = !value;
  }

  get isOpened(): boolean {
    return this._overlay?.isOpened;
  }

  set positions(positions: ConnectionPositionPair[]) {
    this._overlay.positions = positions;
  }

  /**
   * Sets up a stream that will keep track of any newly-added menu items and will update the list
   * of direct descendants. We collect the descendants this way, because `allMenuItems` can include
   * items that are part of child menus, and using a custom way of registering items is unreliable
   * when it comes to maintaining the item order.
   */
  private _updateDirectDescendants(): void {
    this._allMenuItems.changes
      .pipe(startWith(this._allMenuItems), takeUntil(this._destroy$))
      .subscribe((items: QueryList<QLegacyMenuItemComponent>) => {
        this.directDescendantItems.reset(items.filter((item) => item.parentMenu === this));
        this.directDescendantItems.notifyOnChanges();
      });
  }
}
